const SCHEMA = [
  "CREATE TABLE IF NOT EXISTS docs (path TEXT PRIMARY KEY, data TEXT, seq INTEGER NOT NULL, at TEXT)",
  "CREATE INDEX IF NOT EXISTS docs_seq ON docs(seq)",
  // ตัวนับลำดับการเปลี่ยนแปลงที่เพิ่มขึ้นเสมอ (เดิมใช้ MAX(seq) ซึ่งลดลงได้เมื่อลบชิ้นข้อมูล ทำให้เครื่องอื่นพลาดการอัปเดต)
  "CREATE TABLE IF NOT EXISTS seqgen (id INTEGER PRIMARY KEY, v INTEGER NOT NULL)",
  "INSERT OR IGNORE INTO seqgen(id,v) SELECT 1, COALESCE(MAX(seq),0)+5000 FROM docs"
];
let schemaReady = false;
const J = (o, s = 200) => new Response(JSON.stringify(o), { status: s, headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' } });
const okPath = p => typeof p === 'string' && /^[A-Za-z0-9_.~-]+(\/[A-Za-z0-9_.~-]+)*$/.test(p) && p.length <= 200;
const NEXT = "(SELECT v FROM seqgen WHERE id=1)";
const BUMP = "UPDATE seqgen SET v = MAX(v, (SELECT COALESCE(MAX(seq),0) FROM docs)) + 1 WHERE id=1";

export default {
  async fetch(req, env) {
    const url = new URL(req.url);
    if (!url.pathname.startsWith('/api/')) {
      return new Response(HTML, { headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-cache',
        'x-content-type-options': 'nosniff', 'referrer-policy': 'same-origin' } });
    }
    try { return await api(req, env, url); }
    catch (e) { return J({ error: 'server', message: String(e && e.message || e) }, 500); }
  }
};

// ล้างข้อมูลที่ไม่ใช้แล้ว: ชิ้นข้อมูลของเวอร์ชันเก่า (เกิน 10 นาที) และร่องรอยการลบ (เกิน 1 ชั่วโมง) — ฐานข้อมูลไม่บวมขึ้นเรื่อยๆ
async function purge(env) {
  const t10 = new Date(Date.now() - 600000).toISOString(), t60 = new Date(Date.now() - 3600000).toISOString();
  await env.DB.batch([
    env.DB.prepare(`DELETE FROM docs WHERE path LIKE 'chunks/%' AND at < ?1 AND NOT EXISTS (SELECT 1 FROM docs b WHERE b.path LIKE 'branches/%' AND b.data IS NOT NULL AND json_extract(b.data,'$.v') IS NOT NULL AND docs.path LIKE 'chunks/' || substr(b.path,10) || '-' || json_extract(b.data,'$.v') || '-%')`).bind(t10),
    env.DB.prepare('DELETE FROM docs WHERE data IS NULL AND at < ?1').bind(t60)
  ]);
}
async function api(req, env, url) {
  if (!env.DB) return J({ error: 'no_db', message: 'ยังไม่ได้ผูกฐานข้อมูล D1 ชื่อ DB' }, 500);
  if (env.TEAM_CODE && req.headers.get('x-team-code') !== String(env.TEAM_CODE)) return J({ error: 'unauthorized' }, 401);
  if (!schemaReady) {
    await env.DB.batch(SCHEMA.map(s => env.DB.prepare(s)));
    const c = await env.DB.prepare('SELECT COUNT(*) AS n FROM docs').first();
    if (!c.n && SEED.length) {
      const at = new Date().toISOString();
      await env.DB.batch(SEED.map((d, i) => env.DB.prepare('INSERT OR IGNORE INTO docs(path,data,seq,at) VALUES(?1,?2,?3,?4)').bind(d.path, JSON.stringify(d.data), i + 1, at)));
    }
    schemaReady = true;
  }
  const m = req.method, p = url.searchParams.get('p');
  switch (url.pathname) {
    case '/api/ping':
      return J({ ok: true, protected: !!env.TEAM_CODE });
    case '/api/doc': {
      if (!okPath(p)) return J({ error: 'bad_path' }, 400);
      if (m === 'GET') {
        const r = await env.DB.prepare('SELECT data FROM docs WHERE path=?1').bind(p).first();
        return J(r && r.data != null ? { exists: true, data: JSON.parse(r.data) } : { exists: false });
      }
      if (m === 'PUT') {
        const body = await req.text();
        try { JSON.parse(body); } catch (e) { return J({ error: 'bad_json' }, 400); }
        if (body.length > 1900000) return J({ error: 'too_large' }, 413);
        await env.DB.batch([env.DB.prepare(BUMP), env.DB.prepare(`INSERT INTO docs(path,data,seq,at) VALUES(?1,?2,${NEXT},?3)
          ON CONFLICT(path) DO UPDATE SET data=excluded.data, seq=excluded.seq, at=excluded.at`).bind(p, body, new Date().toISOString())]);
        if (p.startsWith('branches/')) await purge(env).catch(() => {});
        return J({ ok: true });
      }
      if (m === 'DELETE') {
        // ชิ้นข้อมูลเก่า (chunks) ลบทิ้งจริงทันที ไม่ต้องเก็บร่องรอย
        if (p.startsWith('chunks/')) await env.DB.prepare('DELETE FROM docs WHERE path=?1').bind(p).run();
        else await env.DB.batch([env.DB.prepare(BUMP), env.DB.prepare(`UPDATE docs SET data=NULL, seq=${NEXT}, at=?2 WHERE path=?1 AND data IS NOT NULL`).bind(p, new Date().toISOString())]);
        return J({ ok: true });
      }
      return J({ error: 'method' }, 405);
    }
    case '/api/list': {
      const c = url.searchParams.get('c');
      if (!okPath(c)) return J({ error: 'bad_path' }, 400);
      const { results } = await env.DB.prepare("SELECT path,data FROM docs WHERE path LIKE ?1 AND data IS NOT NULL ORDER BY path").bind(c + '/%').all();
      return J({ docs: results.filter(r => r.path.indexOf('/', c.length + 1) < 0).map(r => ({ id: r.path.slice(c.length + 1), data: JSON.parse(r.data) })) });
    }
    case '/api/changes': {
      const since = Number(url.searchParams.get('since') || 0);
      const head = await env.DB.prepare('SELECT MAX(COALESCE((SELECT MAX(seq) FROM docs),0), COALESCE((SELECT v FROM seqgen WHERE id=1),0)) AS s').first();
      if (!(since >= 0)) return J({ seq: head.s, changes: [] });
      const { results } = await env.DB.prepare('SELECT path,seq FROM docs WHERE seq>?1 ORDER BY seq LIMIT 1000').bind(since).all();
      return J({ seq: results.length ? results[results.length - 1].seq : head.s, head: head.s, changes: results.map(r => r.path) });
    }
  }
  return J({ error: 'not_found' }, 404);
}
